package com.bananalab.lite;
import android.content.*;import org.json.*;import java.util.*;import java.util.regex.*;
/** Explicit user facts, stable identifiers and individual corrections. No inferred facts. */
final class ProjectMemory{
 static JSONArray rows(SharedPreferences p)throws Exception{String raw=p.getString("facts","[]");JSONArray rows=new JSONArray(raw);int next=1;Set<Integer> used=new HashSet<>();for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);int id=row.optInt("id",0);if(id>0&&!used.add(id))throw new java.io.IOException("Identificadores de memoria duplicados");next=Math.max(next,id+1);}for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(row.optInt("id",0)<=0){while(used.contains(next))next++;row.put("id",next);used.add(next++);}}return rows;}
 static void save(SharedPreferences p,JSONArray rows,int next)throws Exception{if(!p.edit().putString("facts",rows.toString()).putInt("nextId",next).commit())throw new java.io.IOException("No pude guardar el cambio de memoria; intentá de nuevo.");}
 static int next(SharedPreferences p,JSONArray rows)throws Exception{int n=p.getInt("nextId",1);for(int i=0;i<rows.length();i++)n=Math.max(n,rows.getJSONObject(i).getInt("id")+1);return n;}
 static String reply(Context c,String message)throws Exception{
  String q=ChatLanguage.normalize(message);if(!q.matches("(?s)^(?:olvida|borra|quita|corregi|corrige|actualiza|cambia|recorda|recuerda|mi proyecto es|que recordas|que te dije|que dijimos|mis recuerdos|resumi mi proyecto|busca en mis recuerdos).*"))return null;SharedPreferences p=c.getSharedPreferences("banana-project-memory",0);JSONArray rows;try{rows=rows(p);}catch(Exception e){return "No pude leer los recuerdos guardados. No los modifiqué.";}int next=next(p,rows);
  if(q.matches("olvida mis recuerdos|borra mis recuerdos")){if(!p.edit().remove("facts").commit())throw new java.io.IOException("No pude borrar los recuerdos.");return "Borré los recuerdos del proyecto. La escena y las referencias se conservan.";}
  Matcher edit=Pattern.compile("(?:correg[ií]|corrige|actualiz[aá]|cambi[aá]) (?:el )?recuerdo ([0-9]{1,9})\\s*[:=]\\s*(.+)",Pattern.CASE_INSENSITIVE|Pattern.DOTALL).matcher(message.trim());
  Matcher remove=Pattern.compile("(?:olvida|borra|quita) (?:el )?recuerdo ([0-9]{1,9})").matcher(q);
  if(edit.matches()||remove.matches()){boolean editing=edit.matches();int id=Integer.parseInt((editing?edit:remove).group(1)),at=-1;for(int i=0;i<rows.length();i++)if(rows.getJSONObject(i).getInt("id")==id)at=i;if(at<0)return "Ese recuerdo no existe. Pedime ‘mis recuerdos’ para ver sus números.";
   if(editing){String fact=edit.group(2).trim();if(fact.length()<3||fact.length()>400)return "Escribí el recuerdo con entre3 y400 caracteres; conservé el anterior.";JSONObject row=rows.getJSONObject(at);row.put("text",fact).put("updated",System.currentTimeMillis());save(p,rows,next);return "Corregí el recuerdo "+id+": "+fact;}
   JSONArray kept=new JSONArray();for(int i=0;i<rows.length();i++)if(i!=at)kept.put(rows.getJSONObject(i));save(p,kept,next);return "Borré solamente el recuerdo "+id+".";
  }
  String prefix=q.startsWith("recorda que ")?"recorda que ":q.startsWith("recuerda que ")?"recuerda que ":q.startsWith("mi proyecto es ")?"mi proyecto es ":null;
  if(prefix!=null){String fact=message.trim().substring(prefix.length()).trim();if(fact.length()<3||fact.length()>400)return "Decime qué recordar, con entre3 y400 caracteres.";for(int i=0;i<rows.length();i++)if(ChatLanguage.normalize(rows.getJSONObject(i).getString("text")).equals(ChatLanguage.normalize(fact)))return "Ya guardé ese dato como recuerdo "+rows.getJSONObject(i).getInt("id")+".";
   if(rows.length()>=100)return "Llegamos a100 recuerdos. Corregí o borrá alguno antes de agregar otro.";rows.put(new JSONObject().put("id",next).put("text",fact).put("saved",System.currentTimeMillis()));save(p,rows,next+1);return "Guardé lo que me contaste [recuerdo "+next+"]: "+fact;}
  boolean all=q.matches("que recordas|que recordas de mi proyecto|mis recuerdos|resumi mi proyecto");String search=null;for(String start:new String[]{"que te dije sobre ","que recordas sobre ","busca en mis recuerdos ","que dijimos de "})if(q.startsWith(start))search=q.substring(start.length());if(!all&&search==null)return null;
  StringBuilder out=new StringBuilder("Según lo que vos me contaste:");int count=0;for(int i=0;i<rows.length();i++){String fact=rows.getJSONObject(i).getString("text");if(all||matches(fact,search)){out.append("\n[").append(rows.getJSONObject(i).getInt("id")).append("] ").append(fact);count++;}}
  return count==0?"No tengo recuerdos guardados sobre eso. Podés decir ‘recordá que…’.":out.toString();
 }
 static boolean matches(String fact,String query){if(query==null)return false;String normalized=ChatLanguage.normalize(fact);for(String term:query.split(" "))if(term.length()>2&&!term.matches("sobre|recordas|dije|proyecto|quiero|podemos|podes|hacer|decime|ahora|seguimos|contame|para|como|donde")&&Pattern.compile("\\b"+Pattern.quote(term)+"\\b").matcher(normalized).find())return true;return false;}
 static String related(Context c,String message)throws Exception{JSONArray rows;try{rows=rows(c.getSharedPreferences("banana-project-memory",0));}catch(Exception e){return "";}StringBuilder b=new StringBuilder();int count=0;for(int i=rows.length()-1;i>=0&&count<4;i--){String fact=rows.getJSONObject(i).getString("text");if(matches(fact,ChatLanguage.normalize(message))){if(b.length()>0)b.append("; ");b.append(fact.substring(0,Math.min(200,fact.length())));count++;}}return b.toString();}
 static void clear(Context c){c.getSharedPreferences("banana-project-memory",0).edit().clear().apply();}
}
